using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using MecaPlan.Domain.Entities;
namespace MecaPlan.Infrastructure.Persistence.Configurations;
public sealed class EstudianteConfiguration:IEntityTypeConfiguration<Estudiante>{public void Configure(EntityTypeBuilder<Estudiante>b){b.ToTable("Estudiantes","Seguridad");b.HasKey(x=>x.EstudianteID);b.Property(x=>x.Email).HasMaxLength(256).IsRequired();b.Property(x=>x.EmailNormalizado).HasMaxLength(256).IsRequired();b.Property(x=>x.Carnet).HasMaxLength(50).IsRequired();b.Property(x=>x.Nombre).HasMaxLength(100).IsRequired();b.Property(x=>x.Apellido).HasMaxLength(100).IsRequired();b.Property(x=>x.PasswordHash).HasMaxLength(512).IsRequired();b.Property(x=>x.FechaRegistro).HasDefaultValueSql("SYSUTCDATETIME()");b.Property(x=>x.EstadoBit).HasDefaultValue(true).IsRequired();b.HasIndex(x=>x.Carnet).IsUnique().HasDatabaseName("UX_Estudiantes_Carnet");b.HasIndex(x=>x.EmailNormalizado).IsUnique().HasDatabaseName("UX_Estudiantes_EmailNormalizado");}}
public sealed class EventoConfiguration:IEntityTypeConfiguration<EventoAutenticacion>{public void Configure(EntityTypeBuilder<EventoAutenticacion>b){b.ToTable("EventosAutenticacion","Seguridad");b.HasKey(x=>x.IdEventoAutenticacion);b.Property(x=>x.TipoEvento).HasMaxLength(50).IsRequired();b.Property(x=>x.Resultado).HasMaxLength(20).IsRequired();b.Property(x=>x.CorrelationId).HasMaxLength(100).IsRequired();}}
